-- Reviewed manual Operations Risk rollout DML. The batch client must stop on its first error.
-- Assertion failure raises a scalar-subquery cardinality error; disconnect rolls back the transaction.
-- No automatic caller may apply this file. Status/version/timestamps are excluded only from replay identity.
SET NAMES utf8mb4;
USE mor_platform;
START TRANSACTION;
SET @risk_operations_time = UTC_TIMESTAMP(6);

SET @resource_565_version = (SELECT version FROM t_console_resource WHERE `resource_id` = 900000000000000565 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F4D414E4147454D454E54' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '4D454E55' AND `parent_resource_id` IS NULL AND HEX(`display_name`) = 'E9A38EE68EA7E7AEA1E79086' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000536 AND `sort_order` = 30 AND HEX(`status`) IN ('414354495645', '44495341424C4544') AND `version` > 0 FOR UPDATE);
SET @assertion = IF(COALESCE((@resource_565_version > 0), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
SET @resource_566_version = (SELECT version FROM t_console_resource WHERE `resource_id` = 900000000000000566 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F52554C455F434F4E46494755524154494F4E' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '4D454E55' AND `parent_resource_id` = 900000000000000565 AND HEX(`display_name`) = 'E8A784E58899E9858DE7BDAE' AND HEX(`frontend_route`) = '2F7269736B2F72756C652D636F6E66696775726174696F6E' AND HEX(`component_key`) = '4F5045524154494F4E535F5249534B5F52554C455F434F4E46494755524154494F4E' AND `permission_id` = 900000000000000536 AND `sort_order` = 10 AND HEX(`status`) IN ('414354495645', '44495341424C4544') AND `version` > 0 FOR UPDATE);
SET @assertion = IF(COALESCE((@resource_566_version > 0), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
