UPDATE t_console_resource SET status = 'DISABLED', version = version + 1, update_time = @risk_operations_time WHERE resource_id IN (900000000000000565, 900000000000000566, 900000000000000567, 900000000000000568, 900000000000000569, 900000000000000570) AND HEX(status) = '414354495645';
