SET @assertion = IF(COALESCE(((SELECT COUNT(*) FROM t_console_resource WHERE `resource_id` = 900000000000000565 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F4D414E4147454D454E54' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '4D454E55' AND `parent_resource_id` IS NULL AND HEX(`display_name`) = 'E9A38EE68EA7E7AEA1E79086' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000536 AND `sort_order` = 30 AND HEX(status) = '44495341424C4544' AND version = @resource_565_version + IF(@expected_changes = 6, 1, 0)) = 1), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
