SET @assertion = IF(COALESCE(((SELECT COUNT(*) FROM t_console_resource WHERE `resource_id` = 900000000000000567 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F52554C455F5345545F53415645' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '425554544F4E' AND `parent_resource_id` = 900000000000000566 AND HEX(`display_name`) = 'E4BF9DE5AD98E4B8BAE696B0E78988E69CAC' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000537 AND `sort_order` = 10 AND HEX(status) = '44495341424C4544' AND version = @resource_567_version + IF(@expected_changes = 6, 1, 0)) = 1), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
SET @assertion = IF(COALESCE(((SELECT COUNT(*) FROM t_console_resource WHERE `resource_id` = 900000000000000568 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F52554C455F5345545F465245455A45' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '425554544F4E' AND `parent_resource_id` = 900000000000000566 AND HEX(`display_name`) = 'E586BBE7BB93E78988E69CAC' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000538 AND `sort_order` = 20 AND HEX(status) = '44495341424C4544' AND version = @resource_568_version + IF(@expected_changes = 6, 1, 0)) = 1), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
SET @assertion = IF(COALESCE(((SELECT COUNT(*) FROM t_console_resource WHERE `resource_id` = 900000000000000569 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F544553545F43414E4449444154455F435245415445' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '425554544F4E' AND `parent_resource_id` = 900000000000000566 AND HEX(`display_name`) = 'E5889BE5BBBA20544553542043616E646964617465' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000539 AND `sort_order` = 30 AND HEX(status) = '44495341424C4544' AND version = @resource_569_version + IF(@expected_changes = 6, 1, 0)) = 1), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
SET @assertion = IF(COALESCE(((SELECT COUNT(*) FROM t_console_resource WHERE `resource_id` = 900000000000000570 AND HEX(`resource_code`) = '4F5045524154494F4E535F5249534B5F544553545F43414E4449444154455F56414C4944415445' AND HEX(`channel`) = '4F5045524154494F4E53' AND HEX(`resource_type`) = '425554544F4E' AND `parent_resource_id` = 900000000000000566 AND HEX(`display_name`) = 'E689A7E8A18CE99D99E68081E6A0A1E9AA8C' AND `frontend_route` IS NULL AND `component_key` IS NULL AND `permission_id` = 900000000000000540 AND `sort_order` = 40 AND HEX(status) = '44495341424C4544' AND version = @resource_570_version + IF(@expected_changes = 6, 1, 0)) = 1), 0), 1, (SELECT value FROM (SELECT 1 AS value UNION ALL SELECT 2 AS value) AS assertion_failure));
